64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /**
70	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that contains
71	     * at least one dot. Whitespace and additional {@code @} characters are disallowed.
72	     */
73	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
74	
75	    /**
76	     * Common street-type abbreviations expanded during address normalization. Keys and values are
77	     * upper-cased, matching the state of the address after whitespace and case normalization.
78	     */
79	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
80	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
81	
