125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
128	        validateRequiredOwnerFields(ownerFieldsDto);
129	        HttpHeaders headers = new HttpHeaders();
130	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
131	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
132	        owner.setTelephone(normalizedTelephone);
133	        owner.setEmail(normalizeEmail(owner.getEmail()));
134	        owner.setAddress(normalizeAddress(owner.getAddress()));
135	        if (owner.getRegistrationDate() == null) {
136	            owner.setRegistrationDate(LocalDate.now());
137	        }
138	        rejectDuplicateTelephone(normalizedTelephone);
139	        rejectDailyLimitReached(owner.getRegistrationDate());
140	        rejectCityAtCapacity(owner.getCity());
141	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
142	            assignHousehold(owner);
143	        } else {
144	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
145	        }
146	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
147	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
148	        this.clinicService.saveOwner(owner);
149	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
150	        headers.setLocation(UriComponentsBuilder.newInstance()
151	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
152	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
153	    }
