172	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
173	    @Transactional
174	    @Override
175	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
176	        Owner owner = this.clinicService.findOwnerById(ownerId);
177	        if (owner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        this.clinicService.deleteOwner(owner);
181	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
182	    }
