248	
249	    /**
250	     * Builds the customer code for a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
251	     * where {@code CITY3} is the upper-cased first three letters of the owner's city, {@code LAST3}
252	     * is the upper-cased first three letters of the owner's last name, and {@code NNNN} is a per-city
253	     * 4-digit zero-padded sequence equal to one more than the number of owners already in that city.
254	     * For example an owner named "Smithers" in "Springfield" created when 10 owners already live in
255	     * Springfield gets {@code 'SPR-SMI-0011'}.
256	     *
257	     * @param city the owner's city
258	     * @param lastName the owner's last name
259	     * @return the assigned customer code
260	     */
261	    /**
262	     * Counts how many existing owners share the given first and last name, compared
263	     * case-insensitively, at the moment before the new owner is persisted. The result is
264	     * stored on the owner as its {@code namesakeCount}, so it reflects the population as it
265	     * stood when the owner was created rather than being recomputed on later reads.
266	     *
267	     * @param firstName the first name of the owner being created
268	     * @param lastName the last name of the owner being created
269	     * @return the number of pre-existing owners with the same first and last name
270	     */
271	    private int countNamesakes(String firstName, String lastName) {
272	        String first = firstName == null ? "" : firstName;
273	        String last = lastName == null ? "" : lastName;
274	        return (int) this.clinicService.findAllOwners().stream()
275	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
276	                && last.equalsIgnoreCase(existing.getLastName()))
277	            .count();
278	    }
279	
280	    private String nextCustomerCode(String city, String lastName) {
281	        String cityLetters = city == null ? "" : city;
282	        String city3 = cityLetters.substring(0, Math.min(3, cityLetters.length())).toUpperCase(Locale.ROOT);
283	        String letters = lastName == null ? "" : lastName;
284	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
285	        String normalizedCity = normalizeForComparison(city);
286	        int sequence = (int) this.clinicService.findAllOwners().stream()
287	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
288	            .count() + 1;
289	        return String.format("%s-%s-%04d", city3, last3, sequence);
290	    }
291	
292	    /**
293	     * Rejects an owner payload that is missing or blank in any of the required fields
294	     * (firstName, lastName, address, city, telephone). The bean-validation constraints on
295	     * {@link OwnerFieldsDto} already reject {@code null} values and most malformed input, but
296	     * a present-yet-blank {@code address} or {@code city} would otherwise slip through, so this
297	     * guard enforces the rule uniformly for every required field.
298	     *
299	     * @param ownerFieldsDto the submitted owner payload
300	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
301	     */
302	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
303	        List<String> invalidFields = new ArrayList<>();
304	        if (isBlank(ownerFieldsDto.getFirstName())) {
305	            invalidFields.add("firstName");
306	        }
307	        if (isBlank(ownerFieldsDto.getLastName())) {
308	            invalidFields.add("lastName");
309	        }
310	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
311	            invalidFields.add("address");
312	        }
313	        if (isBlank(ownerFieldsDto.getCity())) {
314	            invalidFields.add("city");
315	        }
316	        if (isBlank(ownerFieldsDto.getTelephone())) {
317	            invalidFields.add("telephone");
318	        }
319	        if (!invalidFields.isEmpty()) {
320	            throw new InvalidOwnerFieldsException(invalidFields);
321	        }
322	    }
323	
324	    private boolean isBlank(String value) {
325	        return value == null || value.isBlank();
326	    }
327	
328	    /**
329	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
330	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
331	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
332	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
333	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
334	     *
335	     * @param telephone the raw telephone value from the submitted owner payload
336	     * @return the normalized E.164 telephone number
337	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
338	     */
339	    private String normalizeTelephone(String telephone) {
340	        String raw = telephone == null ? "" : telephone.strip();
341	        boolean hasCountryCode = raw.startsWith("+");
342	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
343	        String digits;
344	        if (hasCountryCode) {
345	            digits = cleaned.substring(1);
346	        } else {
347	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
348	            digits = "61" + national;
349	        }
350	        if (!digits.matches("[0-9]{8,15}")) {
351	            throw new InvalidOwnerFieldsException(List.of("telephone"));
352	        }
353	        return "+" + digits;
354	    }
355	
356	    /**
357	     * Best-effort conversion of an existing telephone value to E.164 form for duplicate comparison,
358	     * returning {@code null} when the value cannot form a valid E.164 number.
359	     *
360	     * @param telephone an existing owner's stored telephone value
361	     * @return the E.164 form, or {@code null} if it cannot be normalized
362	     */
363	    private String toE164OrNull(String telephone) {
364	        try {
365	            return normalizeTelephone(telephone);
366	        } catch (InvalidOwnerFieldsException ex) {
367	            return null;
368	        }
369	    }
370	
371	    /**
372	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
373	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
374	     * accepted value is trimmed and lower-cased before it is stored and returned.
375	     *
376	     * @param email the raw email value from the submitted owner payload, may be {@code null}
377	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
378	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address
379	     */
380	    private String normalizeEmail(String email) {
381	        if (email == null) {
382	            return null;
383	        }
384	        String trimmed = email.strip();
385	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
386	            throw new InvalidOwnerFieldsException(List.of("email"));
387	        }
388	        return trimmed.toLowerCase(Locale.ROOT);
389	    }
390	
391	    /**
392	     * Rejects creating an owner whose E.164 telephone is already used by any other owner.
393	     * Existing owners' telephones are converted to E.164 form before comparison so that
394	     * differently-formatted representations of the same number are treated as duplicates.
395	     *
396	     * @param normalizedTelephone the E.164 telephone of the owner being created
397	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same E.164 telephone
398	     */
399	    private void rejectDuplicateTelephone(String normalizedTelephone) {
400	        boolean duplicate = this.clinicService.findAllOwners().stream()
401	            .map(Owner::getTelephone)
402	            .filter(telephone -> telephone != null)
403	            .map(this::toE164OrNull)
404	            .filter(telephone -> telephone != null)
405	            .anyMatch(normalizedTelephone::equals);
406	        if (duplicate) {
407	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
408	        }
409	    }
410	
411	    /**
412	     * The maximum number of owners a single city may contain. Once a city already holds this many
413	     * owners, creating another owner in that city is rejected.
414	     */
415	    private static final int MAX_OWNERS_PER_CITY = 50;
416	
417	    /**
418	     * Rejects creating an owner in a city that already contains {@link #MAX_OWNERS_PER_CITY} or more
419	     * owners. Existing owners' cities are compared case-insensitively with surrounding and repeated
420	     * internal whitespace collapsed (see {@link #normalizeForComparison}), matching the per-city
421	     * counting used elsewhere.
422	     *
423	     * @param city the city of the owner being created
424	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
425	     */
426	    /**
427	     * The maximum number of owners that may be registered on a single day. Once this many owners
428	     * already share a {@code registrationDate}, creating another owner for that day is rejected.
429	     */
430	    private static final int MAX_OWNERS_PER_DAY = 100;
431	
432	    /**
433	     * Rejects creating an owner on a day that has already reached {@link #MAX_OWNERS_PER_DAY} or more
434	     * owner registrations. Existing owners are counted by their {@code registrationDate} matching the
435	     * registration date of the owner being created.
436	     *
437	     * @param registrationDate the registration date of the owner being created
438	     * @throws DailyOwnerLimitExceededException if the day has already reached the maximum number of owners
439	     */
440	    private void rejectDailyLimitReached(LocalDate registrationDate) {
441	        long ownersToday = this.clinicService.findAllOwners().stream()
442	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
443	            .count();
444	        if (ownersToday >= MAX_OWNERS_PER_DAY) {
445	            throw new DailyOwnerLimitExceededException(registrationDate);
446	        }
447	    }
448	
449	    private void rejectCityAtCapacity(String city) {
450	        String normalizedCity = normalizeForComparison(city);
451	        long ownersInCity = this.clinicService.findAllOwners().stream()
452	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
453	            .count();
454	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
455	            throw new OwnerCityCapacityExceededException(city);
456	        }
457	    }
458	
459	    /**
460	     * Rejects creating an owner whose last name and address both match an existing owner. Both fields
461	     * are compared case-insensitively with surrounding and repeated internal whitespace collapsed, so
462	     * that e.g. {@code "  110  W. Liberty  St. "} and {@code "110 w. liberty st."} are treated as the
463	     * same address. This guard is bypassed for a request that sets {@code sharesHousehold} true.
464	     *
465	     * @param lastName the last name of the owner being created
466	     * @param address the address of the owner being created
467	     * @throws DuplicateOwnerHouseholdException if another owner shares the same last name and address
468	     */
469	    private void rejectDuplicateHousehold(String lastName, String address) {
470	        String normalizedLastName = normalizeForComparison(lastName);
471	        String normalizedAddress = normalizeAddress(address);
472	        boolean duplicate = this.clinicService.findAllOwners().stream()
473	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
474	                && normalizedAddress.equals(normalizeAddress(existing.getAddress())));
475	        if (duplicate) {
476	            throw new DuplicateOwnerHouseholdException(lastName, address);
477	        }
478	    }
479	
480	    /**
481	     * Assigns the owner being created a household identifier when the request opts into sharing a
482	     * household. The identifier is a stable value derived from the owner's normalized last name and
483	     * address (see {@link #householdId}), so every owner in the same household is given the exact same
484	     * value regardless of creation order. Any already-existing owner in the same household that has no
485	     * identifier yet is back-filled with the same value so the whole household stays consistent.
486	     *
487	     * @param owner the owner being created, whose household id is set in place
488	     */
489	    private void assignHousehold(Owner owner) {
490	        String householdId = householdId(owner.getLastName(), owner.getAddress());
491	        String normalizedLastName = normalizeForComparison(owner.getLastName());
492	        String normalizedAddress = normalizeAddress(owner.getAddress());
493	        for (Owner existing : this.clinicService.findAllOwners()) {
494	            if (existing.getHouseholdId() == null
495	                && normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
496	                && normalizedAddress.equals(normalizeAddress(existing.getAddress()))) {
497	                existing.setHouseholdId(householdId);
498	                this.clinicService.saveOwner(existing);
499	            }
500	        }
501	        owner.setHouseholdId(householdId);
502	    }
503	
504	    /**
505	     * Derives the stable household identifier for a given last name and address. The value is
506	     * {@code 'HH-' + <12 upper-case hex chars>} of the SHA-256 digest of the normalized last name and
507	     * address (see {@link #normalizeForComparison}), joined by a delimiter. Two owners that resolve to
508	     * the same household therefore always produce the same identifier.
509	     *
510	     * @param lastName the owner's last name
511	     * @param address the owner's address
512	     * @return the stable household identifier
513	     */
514	    private String householdId(String lastName, String address) {
515	        String key = normalizeForComparison(lastName) + "\n" + normalizeAddress(address);
516	        try {
517	            byte[] digest = MessageDigest.getInstance("SHA-256")
518	                .digest(key.getBytes(StandardCharsets.UTF_8));
519	            StringBuilder hex = new StringBuilder();
520	            for (int i = 0; i < 6; i++) {
521	                hex.append(String.format("%02X", digest[i]));
522	            }
523	            return "HH-" + hex;
524	        } catch (NoSuchAlgorithmException ex) {
525	            throw new IllegalStateException("SHA-256 not available", ex);
526	        }
527	    }
528	
529	    /**
530	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
531	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
532	     * result is lower-cased. A {@code null} value normalizes to the empty string.
533	     *
534	     * @param value the value to normalize, may be {@code null}
535	     * @return the normalized value
536	     */
537	    private String normalizeForComparison(String value) {
538	        if (value == null) {
539	            return "";
540	        }
541	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
542	    }
543	
544	    /**
545	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
546	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
547	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
548	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
549	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
550	     * that is stored, returned, and used for every address comparison (household duplicate detection
551	     * and the shared household id).
552	     *
553	     * @param address the raw address value from the submitted owner payload, may be {@code null}
554	     * @return the normalized address
555	     */
556	    private String normalizeAddress(String address) {
557	        if (address == null) {
558	            return "";
559	        }
560	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
561	        if (collapsed.isEmpty()) {
562	            return "";
563	        }
564	        String[] tokens = collapsed.split(" ");
565	        StringBuilder normalized = new StringBuilder();
566	        for (int i = 0; i < tokens.length; i++) {
567	            if (i > 0) {
568	                normalized.append(' ');
569	            }
570	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
571	        }
572	        return normalized.toString();
573	    }
574	}
